INSERT INTO products (set_number, name, name_no, theme, pieces, price, description, description_no, image_url, stock, age_min) VALUES
('75192', 'Millennium Falcon', 'Millennium Falcon', 'Star Wars', 7541, 3000, 'The most famous ship in the galaxy, this detailed LEGO model features rotating gun turrets, a lowering boarding ramp and landing legs.', 'Det mest berømte romskipet i galaksen med roterende kanonplattformer og landingsrampe.', 'https://images.brickset.com/sets/images/75192-1.jpg', 5, 16),
('10294', 'Titanic', 'Titanic', 'Icons', 9090, 2990, 'Relive the magic of the world''s most famous ocean liner with this incredible LEGO Titanic model featuring over 9,000 pieces.', 'Gjenopplev magien til verdens mest berømte oseanskip med denne utrolige LEGO Titanic-modellen.', 'https://images.brickset.com/sets/images/10294-1.jpg', 3, 18),
('42131', 'CAT D11 Bulldozer', 'CAT D11 Bulldozer', 'Technic', 3854, 2500, 'This massive LEGO Technic CAT D11 Bulldozer features a working blade, ripper, and crawler tracks with full remote control functionality.', 'Denne massive LEGO Technic CAT D11 bulldoseren har fungerende blad, ripper og beltespor med full fjernkontrollfunksjonalitet.', 'https://images.brickset.com/sets/images/42131-1.jpg', 4, 18),
('75978', 'Diagon Alley', 'Diagonalleen', 'Harry Potter', 5544, 2800, 'Explore the magical shops of Diagon Alley in this incredible LEGO Harry Potter set featuring Ollivanders, Weasleys Wizard Wheezes and more.', 'Utforsk de magiske butikkene i Diagonalleen i dette utrolige LEGO Harry Potter-settet med Ollivanders og Weasleys Trollmannsleker.', 'https://images.brickset.com/sets/images/75978-1.jpg', 3, 16),
('10317', 'Land Rover Classic Defender 90', 'Land Rover Classic Defender 90', 'Icons', 2336, 1999, 'Capture the spirit of adventure with this detailed LEGO Icons Land Rover Classic Defender 90 replica with opening bonnet and doors.', 'Fang eventyrets ånd med denne detaljerte LEGO Icons Land Rover Classic Defender 90 replika med åpningspanser og dører.', 'https://images.brickset.com/sets/images/10317-1.jpg', 6, 18),
('21060', 'Himeji Castle', 'Himeji-slottet', 'Architecture', 2125, 1799, 'Discover the beauty of one of Japan''s finest medieval castles with this stunning LEGO Architecture Himeji Castle model.', 'Oppdag skjønnheten til et av Japans fineste middelalderslott med denne fantastiske LEGO Architecture Himeji Castle-modellen.', 'https://images.brickset.com/sets/images/21060-1.jpg', 7, 18),
('10300', 'Back to the Future Time Machine', 'Tilbake til fremtiden Tidsmaskin', 'Icons', 1872, 1499, 'Take a trip back in time with this LEGO Icons Back to the Future Time Machine, featuring the iconic DeLorean in both 1985 and 2015 versions.', 'Ta en reise tilbake i tid med denne LEGO Icons Tilbake til fremtiden Tidsmaskin, med den ikoniske DeLorean i både 1985 og 2015-versjoner.', 'https://images.brickset.com/sets/images/10300-1.jpg', 8, 18),
('75313', 'AT-AT', 'AT-AT', 'Star Wars', 6785, 2800, 'Relive the epic Battle of Hoth with this gigantic LEGO Star Wars Ultimate Collector Series AT-AT model featuring over 6,700 pieces.', 'Gjenopplev det episke Hoth-slaget med denne gigantiske LEGO Star Wars AT-AT-modellen med over 6 700 deler.', 'https://images.brickset.com/sets/images/75313-1.jpg', 5, 18),
('10281', 'Bonsai Tree', 'Bonsai-tre', 'Icons', 878, 499, 'Create a beautiful LEGO bonsai tree display piece that can be customized with either classic green or pink cherry blossom leaves.', 'Lag et vakkert LEGO bonsai-treutstillingsrom som kan tilpasses med enten klassisk grønne eller rosa kirsebærblomsterblader.', 'https://images.brickset.com/sets/images/10281-1.jpg', 15, 18),
('42151', 'Bugatti Bolide', 'Bugatti Bolide', 'Technic', 905, 799, 'Unleash your inner race car driver with this highly detailed LEGO Technic Bugatti Bolide featuring a powerful-looking engine and aerodynamic body.', 'Slipp løs din indre racerbilsjåfør med denne svært detaljerte LEGO Technic Bugatti Bolide med en kraftig motor og aerodynamisk karosseri.', 'https://images.brickset.com/sets/images/42151-1.jpg', 10, 18),
('60380', 'Downtown', 'Bykjernen', 'City', 2010, 1299, 'Build a bustling city center with this LEGO City Downtown set featuring a police station, fire station, apartments, and more.', 'Bygg et livlig bysentrum med dette LEGO City bykjernsettet med politistasjon, brannstasjon, leiligheter og mer.', 'https://images.brickset.com/sets/images/60380-1.jpg', 8, 6),
('76218', 'Sanctum Sanctorum', 'Sanctum Sanctorum', 'Marvel', 2708, 1999, 'Protect the universe from interdimensional threats with this stunning LEGO Marvel Sanctum Sanctorum set featuring 3 floors of Doctor Strange''s home.', 'Beskytt universet mot interdimensjonale trusler med dette fantastiske LEGO Marvel Sanctum Sanctorum-settet med 3 etasjer av Doctor Stranges hjem.', 'https://images.brickset.com/sets/images/76218-1.jpg', 5, 18),
('10270', 'Bookshop', 'Bokhandel', 'Icons', 2504, 1499, 'Build and display a charming bookshop and adjoining apartment in this LEGO Icons Modular Building set, perfect for city displays.', 'Bygg og vis frem en sjarmerende bokhandel og tilstøtende leilighet i dette LEGO Icons modulære byggesett, perfekt for byutstillinger.', 'https://images.brickset.com/sets/images/10270-1.jpg', 6, 16),
('75309', 'Republic Gunship', 'Republikansk Kanonbåt', 'Star Wars', 3292, 2200, 'Build and display this stunning LEGO Star Wars Republic Gunship, featuring incredible detail inspired by the films and animated series.', 'Bygg og vis frem denne fantastiske LEGO Star Wars republikanske kanonbåten med utrolig detalj inspirert av filmene og den animerte serien.', 'https://images.brickset.com/sets/images/75309-1.jpg', 4, 18),
('21042', 'Statue of Liberty', 'Frihetsgudinnen', 'Architecture', 1685, 1199, 'Recreate one of the world''s most famous landmarks with this LEGO Architecture Statue of Liberty model, ideal for display.', 'Gjenskap et av verdens mest kjente landemerker med denne LEGO Architecture Frihetsgudinnen-modellen, ideell for utstilling.', 'https://images.brickset.com/sets/images/21042-1.jpg', 9, 16),
('10297', 'Boutique Hotel', 'Butikkhotell', 'Icons', 3066, 2099, 'Check into this stunning LEGO Icons Boutique Hotel modular building set featuring a detailed facade, rooftop terrace, and interior rooms.', 'Sjekk inn på dette fantastiske LEGO Icons butikkhotell-modulære byggesett med detaljert fasade, takterrasse og interiørrom.', 'https://images.brickset.com/sets/images/10297-1.jpg', 4, 18),
('42143', 'Ferrari Daytona SP3', 'Ferrari Daytona SP3', 'Technic', 3778, 2499, 'Capture the power and elegance of the Ferrari Daytona SP3 with this incredibly detailed LEGO Technic model featuring a V12 engine.', 'Fang kraften og elegansen til Ferrari Daytona SP3 med denne utrolig detaljerte LEGO Technic-modellen med V12-motor.', 'https://images.brickset.com/sets/images/42143-1.jpg', 3, 18),
('76240', 'Batmobile Tumbler', 'Batmobile Tumbler', 'DC', 2049, 1599, 'Recreate the iconic Batmobile Tumbler from The Dark Knight trilogy with this detailed LEGO DC Super Heroes model.', 'Gjenskap den ikoniske Batmobile Tumbler fra The Dark Knight-trilogien med denne detaljerte LEGO DC Super Heroes-modellen.', 'https://images.brickset.com/sets/images/76240-1.jpg', 6, 18),
('21325', 'Medieval Blacksmith', 'Middelaldersk Smed', 'Icons', 2164, 1399, 'Step back in time with this LEGO Icons Medieval Blacksmith set, complete with a detailed forge, living quarters, and market stall.', 'Gå tilbake i tid med dette LEGO Icons middelaldersk smed-settet, komplett med detaljert smi, bolig og markedsbod.', 'https://images.brickset.com/sets/images/21325-1.jpg', 7, 18),
('75257', 'Millennium Falcon', 'Millennium Falcon', 'Star Wars', 1351, 1099, 'Experience the thrilling escape from Jakku with this LEGO Star Wars Millennium Falcon set, compatible with Rey, Finn and more minifigures.', 'Opplev den spennende flukten fra Jakku med dette LEGO Star Wars Millennium Falcon-settet, kompatibelt med Rey, Finn og flere minifigurer.', 'https://images.brickset.com/sets/images/75257-1.jpg', 8, 9),
('10298', 'Vespa 125', 'Vespa 125', 'Icons', 1106, 799, 'Capture the spirit of la dolce vita with this charming LEGO Icons Vespa 125, perfect for display on any shelf or desk.', 'Fang ånden til la dolce vita med denne sjarmerende LEGO Icons Vespa 125, perfekt for utstilling på enhver hylle eller skrivebord.', 'https://images.brickset.com/sets/images/10298-1.jpg', 12, 18),
('42161', 'Lamborghini Huracán Tecnica', 'Lamborghini Huracán Tecnica', 'Technic', 806, 699, 'Bring the thrill of the track home with this LEGO Technic Lamborghini Huracán Tecnica, featuring a detailed V10 engine and opening doors.', 'Ta spenningen fra banen hjem med denne LEGO Technic Lamborghini Huracán Tecnica, med detaljert V10-motor og åpningsdører.', 'https://images.brickset.com/sets/images/42161-1.jpg', 11, 10),
('75341', 'Luke Skywalker''s Landspeeder', 'Luke Skywalkers Landspeeder', 'Star Wars', 1890, 1299, 'Build Luke Skywalker''s iconic Landspeeder in the iconic 1:12 scale with this Ultimate Collector Series LEGO Star Wars model.', 'Bygg Luke Skywalkers ikoniske landspeeder i den ikoniske 1:12 skalaen med denne Ultimate Collector Series LEGO Star Wars-modellen.', 'https://images.brickset.com/sets/images/75341-1.jpg', 6, 18),
('10291', 'Queer Eye – The Fab Five Loft', 'Queer Eye – The Fab Five Loft', 'Icons', 974, 699, 'Celebrate the hit Netflix show Queer Eye with this LEGO Icons Fab Five Loft set, featuring the iconic living space and all five heroes.', 'Feir den populære Netflix-serien Queer Eye med dette LEGO Icons Fab Five Loft-settet, med det ikoniske oppholdsrommet og alle fem helter.', 'https://images.brickset.com/sets/images/10291-1.jpg', 9, 18),
('21336', 'The Office', 'Kontoret', 'Icons', 1164, 899, 'Step into the iconic Dunder Mifflin office from NBC''s hit sitcom The Office with this detailed LEGO Icons set featuring familiar rooms and characters.', 'Tread inn på det ikoniske Dunder Mifflin-kontoret fra NBCs populære sitkom Kontoret med dette detaljerte LEGO Icons-settet.', 'https://images.brickset.com/sets/images/21336-1.jpg', 7, 18),
('60314', 'Ice Cream Truck Heist', 'Iskremvogn-ran', 'City', 317, 299, 'Chase down the bad guys in this exciting LEGO City Ice Cream Truck Heist set, complete with police motorcycle and ice cream truck.', 'Forfølg de slemme gutta i dette spennende LEGO City iskremvogn-ran-settet, komplett med politimotorsykkel og iskremvogn.', 'https://images.brickset.com/sets/images/60314-1.jpg', 20, 6),
('75330', 'Dagobah Jedi Training Diorama', 'Dagobah Jedi Treningsdiorama', 'Star Wars', 1000, 899, 'Relive the iconic Dagobah training scenes from The Empire Strikes Back with this detailed LEGO Star Wars diorama set.', 'Gjenopplev de ikoniske Dagobah-treningsscenene fra Imperiet slår tilbake med dette detaljerte LEGO Star Wars diorama-settet.', 'https://images.brickset.com/sets/images/75330-1.jpg', 8, 18),
('10316', 'The Lord of the Rings: Rivendell', 'Ringenes Herre: Rivendell', 'Icons', 6167, 2999, 'Journey to the elven realm of Rivendell with this spectacular LEGO Icons set featuring an incredibly detailed recreation of the iconic location.', 'Reis til alvenesriket Rivendell med dette spektakulære LEGO Icons-settet med en utrolig detaljert gjenskapelse av den ikoniske lokasjonen.', 'https://images.brickset.com/sets/images/10316-1.jpg', 2, 18),
('42130', 'BMW M 1000 RR', 'BMW M 1000 RR', 'Technic', 1920, 1499, 'Capture every detail of the BMW M 1000 RR superbike in this highly detailed LEGO Technic model with working suspension and steering.', 'Fang alle detaljer til BMW M 1000 RR superbike i denne svært detaljerte LEGO Technic-modellen med fungerende fjæring og styring.', 'https://images.brickset.com/sets/images/42130-1.jpg', 5, 18),
('40577', 'Eiffel Tower', 'Eiffeltårnet', 'Architecture', 10001, 2799, 'Scale new heights with the world''s tallest LEGO set — the Eiffel Tower standing at over 1.5 meters tall, featuring incredible detail.', 'Nå nye høyder med verdens høyeste LEGO-sett — Eiffeltårnet som er over 1,5 meter høyt med utrolig detalj.', 'https://images.brickset.com/sets/images/40577-1.jpg', 3, 18),
('75988', 'Resistance Y-Wing Starfighter', 'Motstandens Y-Wing Stjernekjemper', 'Star Wars', 578, 499, 'Build and battle with this detailed LEGO Star Wars Resistance Y-Wing Starfighter featuring an opening cockpit and minifigures.', 'Bygg og kjemp med denne detaljerte LEGO Star Wars Motstandens Y-Wing Stjernekjemper med åpent cockpit og minifigurer.', 'https://images.brickset.com/sets/images/75249-1.jpg', 14, 9),
('60350', 'Lunar Research Base', 'Måneforskning-base', 'City', 786, 699, 'Explore the lunar surface with this LEGO City Lunar Research Base set featuring a moon buggy, rocket, research lab, and astronaut minifigures.', 'Utforsk månens overflate med dette LEGO City måneforskning-base-settet med månebuggy, rakett, forskningslabb og astronaut-minifigurer.', 'https://images.brickset.com/sets/images/60350-1.jpg', 9, 7),
('21319', 'Central Perk', 'Central Perk', 'Icons', 1070, 799, 'Hang out at the iconic Central Perk coffee shop from Friends with this detailed LEGO Icons set featuring the famous orange sofa and all six characters.', 'Heng ut på den ikoniske Central Perk-kafeen fra Friends med dette detaljerte LEGO Icons-settet med den berømte oransje sofaen og alle seks karakterer.', 'https://images.brickset.com/sets/images/21319-1.jpg', 11, 16),
('42140', 'App-Controlled Transformation Vehicle', 'App-kontrollert Transformasjonskjøretøy', 'Technic', 772, 549, 'Transform from a 4x4 to a 2-wheeled vehicle and back again with this app-controlled LEGO Technic set, featuring seamless motorized transformation.', 'Transformer fra en 4x4 til et 2-hjuls kjøretøy og tilbake igjen med dette app-kontrollerte LEGO Technic-settet.', 'https://images.brickset.com/sets/images/42140-1.jpg', 8, 10),
('76419', 'Hogwarts Castle and Grounds', 'Galtvort slott og omgivelser', 'Harry Potter', 2660, 1999, 'Explore the magical world of Harry Potter with this LEGO Hogwarts Castle and Grounds set, featuring iconic locations from the wizarding world.', 'Utforsk den magiske verden til Harry Potter med dette LEGO Galtvort slott og omgivelser-settet med ikoniske steder fra trollmannsverdenen.', 'https://images.brickset.com/sets/images/76419-1.jpg', 5, 10),
('31120', 'Medieval Castle', 'Middelalderslott', 'Creator', 1426, 999, 'Build a medieval castle, market village or manor house with this 3-in-1 LEGO Creator Medieval Castle set featuring knights, a dragon, and more.', 'Bygg et middelalderslott, landsbymarked eller herregård med dette 3-i-1 LEGO Creator middelalderslott-settet med riddere, en drage og mer.', 'https://images.brickset.com/sets/images/31120-1.jpg', 10, 9),
('10302', 'Optimus Prime', 'Optimus Prime', 'Icons', 1508, 1299, 'Pay tribute to the legendary Autobot leader with this LEGO Icons Optimus Prime model that transforms from robot to truck mode.', 'Hyll den legendariske Autobot-lederen med denne LEGO Icons Optimus Prime-modellen som transformeres fra robot til lastebilmodus.', 'https://images.brickset.com/sets/images/10302-1.jpg', 7, 18),
('60336', 'Freight Train', 'Godstog', 'City', 1153, 1299, 'Load up the LEGO City Freight Train and deliver cargo across the city in this exciting set with remote-controlled locomotive and multiple wagons.', 'Last opp LEGO City godstoget og lever last over hele byen i dette spennende settet med fjernstyrt lokomotiv og flere vogner.', 'https://images.brickset.com/sets/images/60336-1.jpg', 5, 7),
('75304', 'Darth Vader''s Meditation Chamber', 'Darth Vaders meditasjonskammer', 'Star Wars', 663, 499, 'Step into the dark side with this LEGO Star Wars Darth Vader Meditation Chamber set featuring iconic movie scenes and a Darth Vader minifigure.', 'Tred inn på den mørke siden med dette LEGO Star Wars Darth Vader meditasjonskammer-settet med ikoniske filmscener og Darth Vader-minifigur.', 'https://images.brickset.com/sets/images/75296-1.jpg', 13, 8),
('10303', 'Loop Coaster', 'Sløyfe-berg-og-dalbane', 'Icons', 3756, 2299, 'Experience the thrills of a fairground roller coaster with this LEGO Icons Loop Coaster set featuring a fully working coaster mechanism.', 'Opplev spenningen ved en tivolibane med dette LEGO Icons sløyfe-berg-og-dalbane-settet med fullt fungerende bane-mekanisme.', 'https://images.brickset.com/sets/images/10303-1.jpg', 4, 18),
('21333', 'Vincent van Gogh – The Starry Night', 'Vincent van Gogh – Stjernenatt', 'Art', 2316, 1699, 'Recreate one of the most recognizable works of art in the world with this LEGO Art Vincent van Gogh – The Starry Night mosaic set.', 'Gjenskap et av de mest gjenkjennelige kunstverkene i verden med dette LEGO Art Vincent van Gogh – Stjernenatt-mosaikk-settet.', 'https://images.brickset.com/sets/images/31202-1.jpg', 6, 18),
('42141', 'McLaren Formula 1 Race Car', 'McLaren Formel 1 Racerbil', 'Technic', 1432, 1199, 'Build a scale replica of a real McLaren Formula 1 race car with this LEGO Technic set featuring steerable front wheels and a V6 engine.', 'Bygg en skalert replika av en ekte McLaren Formel 1 racerbil med dette LEGO Technic-settet med styrbare forhjul og V6-motor.', 'https://images.brickset.com/sets/images/42141-1.jpg', 7, 18),
('76385', 'Hogwarts Moment: Potions Class', 'Galtvort-øyeblikk: Eliksirtime', 'Harry Potter', 241, 299, 'Recreate potions class at Hogwarts with this fun LEGO Harry Potter Hogwarts Moment set featuring a buildable book, cauldron, and minifigures.', 'Gjenskap eliksirtimen på Galtvort med dette morsomme LEGO Harry Potter Galtvort-øyeblikk-settet med en bygbar bok, gryte og minifigurer.', 'https://images.brickset.com/sets/images/76385-1.jpg', 18, 8),
('60347', 'Grocery Store', 'Dagligvarebutikk', 'City', 1401, 799, 'Open the doors to the LEGO City Grocery Store and help customers find everything they need in this detailed shopping experience set.', 'Åpne dørene til LEGO City dagligvarebutikken og hjelp kunder med å finne alt de trenger i dette detaljerte handleopplevelse-settet.', 'https://images.brickset.com/sets/images/60347-1.jpg', 10, 6),
('21044', 'Paris', 'Paris', 'Architecture', 694, 499, 'Discover the City of Light with this LEGO Architecture Paris skyline set, featuring the Eiffel Tower, Louvre, Notre-Dame and more in miniature.', 'Oppdag lysets by med dette LEGO Architecture Paris-skyline-settet med Eiffeltårnet, Louvre, Notre-Dame og mer i miniatyr.', 'https://images.brickset.com/sets/images/21044-1.jpg', 14, 12),
('76215', 'Black Panther', 'Svart Panter', 'Marvel', 2961, 1999, 'Pay tribute to the legendary King of Wakanda with this stunning LEGO Marvel Black Panther set featuring incredible detail and an iconic display stand.', 'Hyll den legendariske kongen av Wakanda med dette fantastiske LEGO Marvel Svart Panter-settet med utrolig detalj og ikonisk utstillingsstativ.', 'https://images.brickset.com/sets/images/76215-1.jpg', 5, 18),
('10305', 'Lion Knights Castle', 'Løveridder-slott', 'Icons', 4514, 2399, 'Relive the fun of LEGO Castle play with this massive LEGO Icons Lion Knights Castle set featuring towers, a drawbridge, and tons of minifigures.', 'Gjenopplev moroa med LEGO Castle-lek med dette massive LEGO Icons løveridder-slott-settet med tårn, vindebro og massevis av minifigurer.', 'https://images.brickset.com/sets/images/10305-1.jpg', 3, 18),
('60304', 'Road Plates', 'Veifliser', 'City', 112, 199, 'Create your own city layout with these LEGO City Road Plates, perfect for building roads, intersections, and junctions for your vehicles.', 'Lag din egen byplan med disse LEGO City veiflisene, perfekt for å bygge veier, kryss og veikryss for kjøretøyene dine.', 'https://images.brickset.com/sets/images/60304-1.jpg', 25, 5),
('75331', 'Razor Crest', 'Razor Crest', 'Star Wars', 6187, 2700, 'Build the iconic gunship from The Mandalorian with this stunning LEGO Star Wars Ultimate Collector Series Razor Crest model.', 'Bygg det ikoniske kanonbåten fra The Mandalorian med denne fantastiske LEGO Star Wars Ultimate Collector Series Razor Crest-modellen.', 'https://images.brickset.com/sets/images/75331-1.jpg', 3, 18),
('10318', 'Concorde', 'Concorde', 'Icons', 2083, 1499, 'Celebrate the legacy of the world''s first supersonic passenger aircraft with this stunning LEGO Icons Concorde model.', 'Feier arven etter verdens første supersoniske passasjerfly med denne fantastiske LEGO Icons Concorde-modellen.', 'https://images.brickset.com/sets/images/10318-1.jpg', 6, 18);
